arguments.new_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();

// Fix 1 – Captive dependency: scoped IUserService was captured by singleton
// ICacheService. .NET 9 enables ValidateScopes in development, which throws
// InvalidOperationException for this pattern. Align lifetimes.
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// Fix 2 – HttpClientFactory now uses SocketsHttpHandler by default.
// Casting PrimaryHandler to HttpClientHandler throws InvalidCastException.
// Use ConfigurePrimaryHttpMessageHandler to set properties directly.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() =>
        new SocketsHttpHandler { UseCookies = false });

// Fix 3 – Forwarded Headers middleware now ignores X-Forwarded-* headers
// from proxies not in KnownProxies/KnownNetworks. Configure your trusted
// proxy addresses here.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // TODO: replace with your actual proxy address(es)
    options.KnownProxies.Add(System.Net.IPAddress.Parse("10.0.0.1"));
});

// Fix 4 – HttpClientFactory now redacts ALL header values in Trace-level
// logs. Allowlist the non-sensitive headers you need for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id"
        && h != "X-Correlation-Id"
        && h != "Cache-Control"
        && h != "Accept"));

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

